  ('voc_toeic_0251', 'deck_toeic_990', 'en', 'prompt', 'prompt', '/prɒmpt/', 'nhanh chóng, mau lẹ kịp thời', 'We take pride in providing prompt and courteous responses to client emails.', '750-990+', 'adj', 'TOEIC,990,Unit-09', 'imported', 'toeic_09_11', 1),
