  ('voc_toeic_0253', 'deck_toeic_990', 'en', 'redress', 'redress', '/rɪˈdres/', 'sự bồi thường thỏa đáng; đền bù thiệt hại', 'The consumer protection agency helps victims seek redress against misleading claims.', '750-990+', 'n, v', 'TOEIC,990,Unit-09', 'imported', 'toeic_09_13', 1),
  ('voc_toeic_0254', 'deck_toeic_990', 'en', 'hotline', 'hotline', '/ˈhɒtlaɪn/', 'đường dây nóng hỗ trợ khẩn cấp', 'The technical support hotline operates twenty-four hours a day, seven days a week.', '750-990+', 'n', 'TOEIC,990,Unit-09', 'imported', 'toeic_09_14', 1),
  ('voc_toeic_0255', 'deck_toeic_990', 'en', 'dispute', 'dispute', '/dɪˈspjuːt/', 'tranh chấp giao dịch, bất đồng ý kiến', 'Cardholders can dispute unauthorized charges directly through their online portal.', '750-990+', 'n, v', 'TOEIC,990,Unit-09', 'imported', 'toeic_09_15', 1),
