  ('voc_toeic_0447', 'deck_toeic_990', 'en', 'deteriorate', 'deteriorate', '/dɪˈtɪəriəreɪt/', 'xuống cấp, suy thoái chất lượng', 'Without regular weather sealing, wooden window frames rapidly deteriorate.', '750-990+', 'v', 'TOEIC,990,Unit-15', 'imported', 'toeic_15_27', 1),
  ('voc_toeic_0448', 'deck_toeic_990', 'en', 'cleanroom', 'cleanroom', '/ˈkliːnruːm/', 'phòng sạch tiệt trùng chế tạo vi mạch', 'Specialist cleanroom facilities prevent microscopic dust from ruining microchips.', '750-990+', 'n', 'TOEIC,990,Unit-15', 'imported', 'toeic_15_28', 1),
  ('voc_toeic_0449', 'deck_toeic_990', 'en', 'fire extinguisher', 'fire extinguisher', '/ˈfaɪər ɪkˈstɪŋɡwɪʃə(r)/', 'bình chữa cháy cầm tay', 'Fire extinguishers are stationed next to every emergency exit stairway.', '750-990+', 'n phr', 'TOEIC,990,Unit-15', 'imported', 'toeic_15_29', 1),
  ('voc_toeic_0450', 'deck_toeic_990', 'en', 'evacuation', 'evacuation', '/ɪˌvækjuˈeɪʃn/', 'sự sơ tán khẩn cấp khỏi tòa nhà', 'Employees assembled in the north parking lot during the unannounced evacuation drill.', '750-990+', 'n', 'TOEIC,990,Unit-15', 'imported', 'toeic_15_30', 1);

INSERT OR REPLACE INTO vocabulary (
  id, deck_id, language, word, normalized_word, pronunciation, meaning_vi, example, level, part_of_speech, tags, source_type, seed_key, seed_version
) VALUES
  ('voc_toeic_0451', 'deck_toeic_990', 'en', 'assembly line', 'assembly line', '/əˈsembli laɪn/', 'dây chuyền lắp ráp tự động', 'Robotic arms on the assembly line can mount automotive doors in forty seconds.', '750-990+', 'n phr', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_01', 1),
  ('voc_toeic_0452', 'deck_toeic_990', 'en', 'manufacture', 'manufacture', '/ˌmænjuˈfæktʃə(r)/', 'sản xuất công nghiệp; ngành sản xuất', 'The factory manufactures medical diagnostic equipment for global export.', '750-990+', 'v, n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_02', 1),
  ('voc_toeic_0453', 'deck_toeic_990', 'en', 'component', 'component', '/kəmˈpəʊnənt/', 'linh kiện, bộ phận cấu thành', 'Each electronic component is rigorously inspected prior to final chassis assembly.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_03', 1),
  ('voc_toeic_0454', 'deck_toeic_990', 'en', 'raw material', 'raw material', '/rɔː məˈtɪəriəl/', 'nguyên liệu thô ban đầu', 'Rising international costs for raw materials forced prices up by twelve percent.', '750-990+', 'n phr', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_04', 1),
  ('voc_toeic_0455', 'deck_toeic_990', 'en', 'output', 'output', '/ˈaʊtpʊt/', 'sản lượng đầu ra sản xuất', 'Factory output reached a record high of 50,000 units this past quarter.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_05', 1),
  ('voc_toeic_0456', 'deck_toeic_990', 'en', 'capacity', 'capacity', '/kəˈpæsəti/', 'công suất sản xuất tối đa', 'The steel mill is operating at 95% capacity to satisfy soaring infrastructure demand.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_06', 1),
  ('voc_toeic_0457', 'deck_toeic_990', 'en', 'bottleneck', 'bottleneck', '/ˈbɒtlnek/', 'điểm nghẽn gây chậm cả dây chuyền', 'The packaging station turned out to be the primary bottleneck in manufacturing.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_07', 1),
  ('voc_toeic_0458', 'deck_toeic_990', 'en', 'robotics', 'robotics', '/rəʊˈbɒtɪks/', 'công nghệ robot chế tạo tự động', 'Investing in factory robotics streamlined the automobile door assembly line.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_08', 1),
  ('voc_toeic_0459', 'deck_toeic_990', 'en', 'machinery', 'machinery', '/məˈʃiːnəri/', 'máy móc thiết bị sản xuất nặng', 'Operators must don protective headgear when working near heavy stamping machinery.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_09', 1),
  ('voc_toeic_0460', 'deck_toeic_990', 'en', 'fabricate', 'fabricate', '/ˈfæbrɪkeɪt/', 'chế tạo, gia công cơ khí chính xác', 'Specialized CNC lasers fabricate titanium aircraft brackets within tiny tolerances.', '750-990+', 'v', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_10', 1),
  ('voc_toeic_0461', 'deck_toeic_990', 'en', 'subcontractor', 'subcontractor', '/ˌsʌbkənˈtræktə(r)/', 'nhà thầu phụ gia công linh kiện', 'The primary contractor hired subcontractors to handle precision electronic soldering.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_11', 1),
  ('voc_toeic_0462', 'deck_toeic_990', 'en', 'prototype', 'prototype', '/ˈprəʊtətaɪp/', 'mẫu thử nghiệm đầu tiên (nguyên mẫu)', 'Engineers put the battery prototype through extreme temperature durability tests.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_12', 1),
  ('voc_toeic_0463', 'deck_toeic_990', 'en', 'production quota', 'production quota', '/prəˈdʌkʃn ˈkwəʊtə/', 'chỉ tiêu sản lượng sản xuất', 'The night shift easily exceeded its daily production quota by 150 units.', '750-990+', 'n phr', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_13', 1),
  ('voc_toeic_0464', 'deck_toeic_990', 'en', 'idle time', 'idle time', '/ˈaɪdl taɪm/', 'thời gian máy móc ngừng nghỉ chờ hàng', 'Optimizing tool changeovers minimized costly machine idle time.', '750-990+', 'n phr', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_14', 1),
  ('voc_toeic_0465', 'deck_toeic_990', 'en', 'throughput', 'throughput', '/ˈθruːpʊt/', 'lượng sản phẩm xử lý qua hệ thống', 'Upgraded hydraulic pumps doubled the chemical plant’s processing throughput.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_15', 1),
  ('voc_toeic_0466', 'deck_toeic_990', 'en', 'foundry', 'foundry', '/ˈfaʊndri/', 'xưởng đúc kim loại/chế tạo bán dẫn', 'The semiconductor foundry produces millions of microprocessors every week.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_16', 1),
  ('voc_toeic_0467', 'deck_toeic_990', 'en', 'standardize', 'standardize', '/ˈstændədaɪz/', 'tiêu chuẩn hóa quy trình kỹ thuật', 'We standardized screw sizes across all product lines to simplify manufacturing.', '750-990+', 'v', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_17', 1),
  ('voc_toeic_0468', 'deck_toeic_990', 'en', 'conveyor belt', 'conveyor belt', '/kənˈveɪə belt/', 'băng chuyền tải hàng sản xuất', 'Cartons glide down the conveyor belt directly into the automated palletizer.', '750-990+', 'n phr', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_18', 1),
  ('voc_toeic_0469', 'deck_toeic_990', 'en', 'wear', 'wear', '/weə(r)/', 'sự hao mòn của lưỡi cắt/linh kiện máy', 'Tool wear was monitored continuously by vibration and acoustic sensors.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_19', 1),
  ('voc_toeic_0470', 'deck_toeic_990', 'en', 'mass production', 'mass production', '/mæs prəˈdʌkʃn/', 'sản xuất hàng loạt quy mô công nghiệp', 'Mass production of the new electric crossover will commence early next spring.', '750-990+', 'n phr', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_20', 1),
  ('voc_toeic_0471', 'deck_toeic_990', 'en', 'plant', 'plant', '/plɑːnt/', 'nhà máy công nghiệp quy mô lớn', 'The chemical processing plant underwent a comprehensive environmental audit.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_21', 1),
  ('voc_toeic_0472', 'deck_toeic_990', 'en', 'retooling', 'retooling', '/ˌriːˈtuːlɪŋ/', 'thay đổi dây chuyền công cụ chế tạo mới', 'The assembly plant underwent a three-week retooling to manufacture electric vehicles.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_22', 1),
  ('voc_toeic_0473', 'deck_toeic_990', 'en', 'defect rate', 'defect rate', '/ˈdiːfekt reɪt/', 'tỷ lệ sản phẩm lỗi hỏng', 'Precision calibration helped reduce the factory’s defect rate to under 0.02%.', '750-990+', 'n phr', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_23', 1),
  ('voc_toeic_0474', 'deck_toeic_990', 'en', 'machinist', 'machinist', '/məˈʃiːnɪst/', 'thợ cơ khí vận hành máy tiện/phay', 'A skilled machinist programmed the multi-axis lathe to sculpt turbine blades.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_24', 1),
  ('voc_toeic_0475', 'deck_toeic_990', 'en', 'lot number', 'lot number', '/lɒt ˈnʌmbə(r)/', 'số lô sản phẩm sản xuất để truy xuất', 'Inspect the printed lot number on the packaging if reporting a defective batch.', '750-990+', 'n phr', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_25', 1),
  ('voc_toeic_0476', 'deck_toeic_990', 'en', 'workforce', 'workforce', '/ˈwɜːkfɔːs/', 'lực lượng lao động nhà máy', 'The manufacturing plant employs a skilled workforce of over eight hundred technicians.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_26', 1),
  ('voc_toeic_0477', 'deck_toeic_990', 'en', 'custom-made', 'custom-made', '/ˌkʌstəm ˈmeɪd/', 'sản xuất đặt riêng theo yêu cầu', 'The client ordered custom-made stainless-steel fittings for their brewery.', '750-990+', 'adj', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_27', 1),
  ('voc_toeic_0478', 'deck_toeic_990', 'en', 'shift', 'shift', '/ʃɪft/', 'ca làm việc tại nhà máy', 'Factory operators work rotating eight-hour shifts to keep production humming.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_28', 1),
  ('voc_toeic_0479', 'deck_toeic_990', 'en', 'supply chain', 'supply chain', '/səˈplaɪ tʃeɪn/', 'chuỗi cung ứng sản xuất', 'Disruptions in the overseas supply chain delayed automobile delivery dates.', '750-990+', 'n phr', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_29', 1),
  ('voc_toeic_0480', 'deck_toeic_990', 'en', 'silo', 'silo', '/ˈsaɪləʊ/', 'tháp/kho silo chứa vật liệu rời', 'Grain and industrial plastics are stored in high-capacity vertical silos.', '750-990+', 'n', 'TOEIC,990,Unit-16', 'imported', 'toeic_16_30', 1),
  ('voc_toeic_0481', 'deck_toeic_990', 'en', 'quality control', 'quality control', '/ˈkwɒləti kənˈtrəʊl/', 'kiểm soát chất lượng sản phẩm (QC)', 'The quality control team conducts random sample testing on every finished batch.', '750-990+', 'n phr', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_01', 1),
  ('voc_toeic_0482', 'deck_toeic_990', 'en', 'compliance', 'compliance', '/kəmˈplaɪəns/', 'sự tuân thủ tiêu chuẩn, quy chuẩn luật', 'Our factories operate in strict compliance with federal environmental laws.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_02', 1),
  ('voc_toeic_0483', 'deck_toeic_990', 'en', 'surveillance', 'surveillance', '/sɜːˈveɪləns/', 'sự giám sát theo dõi quy trình kỹ thuật', 'Continuous video surveillance ensures that cleanroom clean standards are maintained.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_03', 1),
  ('voc_toeic_0484', 'deck_toeic_990', 'en', 'standard', 'standard', '/ˈstændəd/', 'tiêu chuẩn chất lượng/kỹ thuật', 'Products must meet international ISO 9001 standards to earn certification.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_04', 1),
  ('voc_toeic_0485', 'deck_toeic_990', 'en', 'calibration', 'calibration', '/ˌkælɪˈbreɪʃn/', 'sự hiệu chuẩn đo lường chính xác', 'Laser measurement tools require bi-monthly calibration by certified technicians.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_05', 1),
  ('voc_toeic_0486', 'deck_toeic_990', 'en', 'flaw', 'flaw', '/flɔː/', 'tì vết, khuyết tật nhỏ của sản phẩm', 'Microscopic camera sensors detect the slightest optical flaws on glass lenses.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_06', 1),
  ('voc_toeic_0487', 'deck_toeic_990', 'en', 'tolerance', 'tolerance', '/ˈtɒlərəns/', 'dung sai kỹ thuật cho phép', 'Aerospace parts must be machined within a microscopic tolerance of 0.005 mm.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_07', 1),
  ('voc_toeic_0488', 'deck_toeic_990', 'en', 'yardstick', 'yardstick', '/ˈjɑːdstɪk/', 'thước đo tiêu chuẩn đánh giá', 'Energy efficiency has become the primary yardstick for evaluating appliances.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_08', 1),
  ('voc_toeic_0489', 'deck_toeic_990', 'en', 'certification', 'certification', '/ˌsɜːtɪfɪˈkeɪʃn/', 'chứng chỉ chứng nhận chất lượng', 'The facility attained formal certification for organic food processing.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_09', 1),
  ('voc_toeic_0490', 'deck_toeic_990', 'en', 'scrutiny', 'scrutiny', '/ˈskruːtəni/', 'sự kiểm tra xem xét kỹ lưỡng tỉ mỉ', 'The pharmaceutical company’s trial data came under intense regulatory scrutiny.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_10', 1),
  ('voc_toeic_0491', 'deck_toeic_990', 'en', 'verify', 'verify', '/ˈverɪfaɪ/', 'xác minh, kiểm chứng độ chính xác', 'Auditors reviewed laboratory test logs to verify safety claims.', '750-990+', 'v', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_11', 1),
  ('voc_toeic_0492', 'deck_toeic_990', 'en', 'adhere to', 'adhere to', '/ədˈhɪə tuː/', 'tuân thủ nghiêm ngặt tiêu chuẩn', 'All contract assemblers must strictly adhere to statutory hygiene protocols.', '750-990+', 'phr v', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_12', 1),
  ('voc_toeic_0493', 'deck_toeic_990', 'en', 'discard', 'discard', '/dɪˈskɑːd/', 'loại bỏ, vứt bỏ hàng không đạt chuẩn', 'Any canned goods showing signs of denting or seal damage must be discarded.', '750-990+', 'v', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_13', 1),
  ('voc_toeic_0494', 'deck_toeic_990', 'en', 'rigorous', 'rigorous', '/ˈrɪɡərəs/', 'khắt khe, nghiêm ngặt, chuẩn xác', 'The vaccine underwent months of rigorous clinical testing before market approval.', '750-990+', 'adj', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_14', 1),
  ('voc_toeic_0495', 'deck_toeic_990', 'en', 'peer review', 'peer review', '/pɪə rɪˈvjuː/', 'đánh giá chéo ngang hàng giữa các chuyên gia', 'All pharmaceutical trial protocols must pass rigorous academic peer review.', '750-990+', 'n phr', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_15', 1),
  ('voc_toeic_0496', 'deck_toeic_990', 'en', 'conformity', 'conformity', '/kənˈfɔːməti/', 'sự phù hợp tiêu chuẩn quy định', 'Certificates of conformity must accompany every shipment of steel rebar.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_16', 1),
  ('voc_toeic_0497', 'deck_toeic_990', 'en', 'rectify', 'rectify', '/ˈrektɪfaɪ/', 'chỉnh sửa, khắc phục sai sót kỹ thuật', 'The engineering team acted immediately to rectify the firmware vulnerability.', '750-990+', 'v', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_17', 1),
  ('voc_toeic_0498', 'deck_toeic_990', 'en', 'paramount', 'paramount', '/ˈpærəmaʊnt/', 'tối quan trọng, có ý nghĩa hàng đầu', 'Worker safety and product integrity are of paramount importance to our executive board.', '750-990+', 'adj', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_18', 1),
  ('voc_toeic_0499', 'deck_toeic_990', 'en', 'substandard', 'substandard', '/ˌsʌbˈstændəd/', 'dưới chuẩn, kém chất lượng không đạt yêu cầu', 'Substandard building materials were rejected by the head structural engineer.', '750-990+', 'adj', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_19', 1),
  ('voc_toeic_0500', 'deck_toeic_990', 'en', 'sampling', 'sampling', '/ˈsɑːmplɪŋ/', 'hoạt động lấy mẫu kiểm tra ngẫu nhiên', 'Statistical sampling allows quality managers to evaluate millions of pills swiftly.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_20', 1);

INSERT OR REPLACE INTO vocabulary (
  id, deck_id, language, word, normalized_word, pronunciation, meaning_vi, example, level, part_of_speech, tags, source_type, seed_key, seed_version
) VALUES
  ('voc_toeic_0501', 'deck_toeic_990', 'en', 'deviation', 'deviation', '/ˌdiːviˈeɪʃn/', 'độ lệch chuẩn so với thông số thiết kế', 'Any deviation greater than two millimeters results in immediate part rejection.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_21', 1),
  ('voc_toeic_0502', 'deck_toeic_990', 'en', 'integrity', 'integrity', '/ɪnˈteɡrəti/', 'sự vẹn toàn, tính toàn vẹn kết cấu', 'Ultrasonic sensors test the structural integrity of welded airplane wings.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_22', 1),
  ('voc_toeic_0503', 'deck_toeic_990', 'en', 'procedural guideline', 'procedural guideline', '/prəˈsiːdʒərəl ˈɡaɪdlaɪn/', 'hướng dẫn quy trình thao tác chuẩn', 'Lab technicians must follow procedural guidelines for hazardous waste disposal.', '750-990+', 'n phr', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_23', 1),
  ('voc_toeic_0504', 'deck_toeic_990', 'en', 'accreditation', 'accreditation', '/əˌkredɪˈteɪʃn/', 'sự kiểm định công nhận chất lượng', 'The testing laboratory achieved ISO/IEC 17025 accreditation for forensic analysis.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_24', 1),
  ('voc_toeic_0505', 'deck_toeic_990', 'en', 'rejection rate', 'rejection rate', '/rɪˈdʒekʃn reɪt/', 'tỷ lệ từ chối loại bỏ hàng lỗi', 'Automating the solder line reduced the component rejection rate to near zero.', '750-990+', 'n phr', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_25', 1),
  ('voc_toeic_0506', 'deck_toeic_990', 'en', 'tolerance limit', 'tolerance limit', '/ˈtɒlərəns ˈlɪmɪt/', 'giới hạn dung sai kích thước cho phép', 'Components that exceed strict tolerance limits are immediately melted down.', '750-990+', 'n phr', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_26', 1),
  ('voc_toeic_0507', 'deck_toeic_990', 'en', 'traceability', 'traceability', '/ˌtreɪsəˈbɪləti/', 'khả năng truy xuất nguồn gốc sản phẩm', 'Barcoding every crate guarantees end-to-end traceability across the supply chain.', '750-990+', 'n', 'TOEIC,990,Unit-17', 'imported', 'toeic_17_27', 1),
