  ('voc_toeic_0806', 'deck_toeic_990', 'en', 'sub-assign', 'sub-assign', '/sʌb əˈsaɪn/', 'phân công giao việc thứ cấp cho tổ đội', 'Team captains sub-assign smaller programming tickets to junior developers.', '750-990+', 'v', 'TOEIC,990,Unit-27', 'imported', 'toeic_27_26', 1),
