  ('voc_toeic_0809', 'deck_toeic_990', 'en', 'oversight', 'oversight', '/ˈəʊvəsaɪt/', 'sự giám sát chỉ đạo; sơ suất bỏ quên', 'The oversight committee monitors high-risk expenditures to prevent embezzlement.', '750-990+', 'n', 'TOEIC,990,Unit-27', 'imported', 'toeic_27_29', 1),
  ('voc_toeic_0810', 'deck_toeic_990', 'en', 'deliver', 'deliver', '/dɪˈlɪvə(r)/', 'hoàn thành và bàn giao sản phẩm đúng hẹn', 'The team worked relentlessly to deliver the mobile banking platform before Q4.', '750-990+', 'v', 'TOEIC,990,Unit-27', 'imported', 'toeic_27_30', 1),
  ('voc_toeic_0811', 'deck_toeic_990', 'en', 'notwithstanding', 'notwithstanding', '/ˌnɒtwɪθˈstændɪŋ/', 'mặc dù, bất kể (= despite / in spite of)', 'Notwithstanding severe supply shortages, the manufacturing team hit its quarterly quota.', '750-990+', 'prep', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_01', 1),
