  ('voc_toeic_0813', 'deck_toeic_990', 'en', 'consequently', 'consequently', '/ˈkɒnsɪkwəntli/', 'do đó, hệ quả là (= as a result / therefore)', 'Consumer demand plunged; consequently, retail inventory sat unpurchased on warehouse shelves.', '750-990+', 'adv', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_03', 1),
  ('voc_toeic_0814', 'deck_toeic_990', 'en', 'nevertheless', 'nevertheless', '/ˌnevəðəˈles/', 'tuy nhiên, dù vậy (= however / nonetheless)', 'Economic forecasts look gloomy; nevertheless, the firm plans to expand its regional branches.', '750-990+', 'adv', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_04', 1),
  ('voc_toeic_0815', 'deck_toeic_990', 'en', 'whereas', 'whereas', '/ˌweərˈæz/', 'trong khi đó (chỉ sự đối lập tương phản)', 'Online sales skyrocketed by 40%, whereas foot traffic at brick-and-mortar stores fell.', '750-990+', 'conj', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_05', 1),
