  ('voc_toeic_0817', 'deck_toeic_990', 'en', 'in the event of', 'in the event of', '/ɪn ði ɪˈvent əv/', 'trong trường hợp xảy ra việc gì (= in case of)', 'In the event of a fire alarm, immediately evacuate via the nearest illuminated stairwell.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_07', 1),
  ('voc_toeic_0818', 'deck_toeic_990', 'en', 'given that', 'given that', '/ˈɡɪvn ðæt/', 'xét đến việc, căn cứ vào việc (= considering that)', 'Given that raw material costs have doubled, a price increase on finished goods is inevitable.', '750-990+', 'conj phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_08', 1),
  ('voc_toeic_0819', 'deck_toeic_990', 'en', 'on behalf of', 'on behalf of', '/ɒn bɪˈhɑːf əv/', 'thay mặt cho, đại diện cho ai', 'On behalf of the board of directors, I would like to welcome our esteemed keynote guests.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_09', 1),
  ('voc_toeic_0820', 'deck_toeic_990', 'en', 'in light of', 'in light of', '/ɪn laɪt əv/', 'bởi vì, căn cứ theo tình hình (= because of)', 'In light of recent budget constraints, all non-essential business travel is canceled.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_10', 1),
  ('voc_toeic_0821', 'deck_toeic_990', 'en', 'regardless of', 'regardless of', '/rɪˈɡɑːdləs əv/', 'bất kể, không màng tới (= irrespective of)', 'All eligible staff may apply for the fellowship regardless of length of tenure.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_11', 1),
  ('voc_toeic_0822', 'deck_toeic_990', 'en', 'subsequent to', 'subsequent to', '/ˈsʌbsɪkwənt tuː/', 'sau khi, tiếp sau sự việc (= following / after)', 'Subsequent to the board meeting, an official corporate memorandum was circulated.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_12', 1),
  ('voc_toeic_0823', 'deck_toeic_990', 'en', 'prior to', 'prior to', '/ˈpraɪə tuː/', 'trước khi (= before)', 'All visitors must present valid photo identification prior to entering the server facility.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_13', 1),
  ('voc_toeic_0824', 'deck_toeic_990', 'en', 'in accordance with', 'in accordance with', '/ɪn əˈkɔːdns wɪð/', 'phù hợp với, tuân theo quy định', 'Annual financial audits must be performed in accordance with federal accounting guidelines.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_14', 1),
  ('voc_toeic_0825', 'deck_toeic_990', 'en', 'as opposed to', 'as opposed to', '/æz əˈpəʊzd tuː/', 'thay vì, đối lập hẳn với', 'We selected a cloud solution as opposed to constructing an expensive on-premise datacenter.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_15', 1),
  ('voc_toeic_0826', 'deck_toeic_990', 'en', 'in addition to', 'in addition to', '/ɪn əˈdɪʃn tuː/', 'bên cạnh, ngoài ra còn (= besides / aside from)', 'In addition to competitive base wages, the job offer includes comprehensive healthcare perks.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_16', 1),
  ('voc_toeic_0827', 'deck_toeic_990', 'en', 'owing to', 'owing to', '/ˈəʊɪŋ tuː/', 'nhờ vào, do vì (= due to / because of)', 'Flight cancellations were widespread owing to severe zero-visibility blizzard conditions.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_17', 1),
  ('voc_toeic_0828', 'deck_toeic_990', 'en', 'in spite of', 'in spite of', '/ɪn spaɪt əv/', 'mặc dù, bất chấp (= despite)', 'In spite of fierce market competition, the tech startup captured a 15% domestic market share.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_18', 1),
  ('voc_toeic_0829', 'deck_toeic_990', 'en', 'meanwhile', 'meanwhile', '/ˈmiːnwaɪl/', 'trong lúc đó, trong khi chờ đợi', 'The CEO addressed foreign journalists; meanwhile, technicians tested the demo equipment.', '750-990+', 'adv', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_19', 1),
  ('voc_toeic_0830', 'deck_toeic_990', 'en', 'hence', 'hence', '/hens/', 'do đó, vì lý do ấy (= therefore)', 'The merger creates unmatched synergies, hence our supreme confidence in next year’s revenue.', '750-990+', 'adv', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_20', 1),
  ('voc_toeic_0831', 'deck_toeic_990', 'en', 'likewise', 'likewise', '/ˈlaɪkwaɪz/', 'tương tự như vậy, cũng thế (= similarly)', 'Our European branch reported soaring revenues, and domestic operations performed likewise.', '750-990+', 'adv', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_21', 1),
  ('voc_toeic_0832', 'deck_toeic_990', 'en', 'inasmuch as', 'inasmuch as', '/ˌɪnəzˈmʌtʃ æz/', 'bởi vì, xét thấy rằng (= since / seeing that)', 'Inasmuch as the tenant breached the lease covenant, the landlord commenced eviction proceedings.', '750-990+', 'conj', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_22', 1),
  ('voc_toeic_0833', 'deck_toeic_990', 'en', 'concerning', 'concerning', '/kənˈsɜːnɪŋ/', 'liên quan tới, về vấn đề (= regarding / about)', 'Call human resources if you have questions concerning the updated healthcare benefits.', '750-990+', 'prep', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_23', 1),
  ('voc_toeic_0834', 'deck_toeic_990', 'en', 'pertaining to', 'pertaining to', '/pəˈteɪnɪŋ tuː/', 'thuộc về, liên quan mật thiết tới', 'Documents pertaining to the corporate acquisition were locked inside the legal vault.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_24', 1),
  ('voc_toeic_0835', 'deck_toeic_990', 'en', 'except for', 'except for', '/ɪkˈsept fɔː(r)/', 'ngoại trừ, trừ trường hợp', 'The executive offices are closed on weekends except for authorized security personnel.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_25', 1),
  ('voc_toeic_0836', 'deck_toeic_990', 'en', 'unless', 'unless', '/ənˈles/', 'trừ khi, nếu không (= if not)', 'Contracts cannot be signed unless both parties have reviewed the finalized clause addenda.', '750-990+', 'conj', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_26', 1),
  ('voc_toeic_0837', 'deck_toeic_990', 'en', 'so that', 'so that', '/səʊ ðæt/', 'để mà (chỉ mục đích hành động)', 'Please speak clearly into the microphone so that delegates in the gallery can hear.', '750-990+', 'conj', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_27', 1),
  ('voc_toeic_0838', 'deck_toeic_990', 'en', 'as though', 'as though', '/æz ðəʊ/', 'như thể là (= as if)', 'The stock market rallied strongly as though interest rates had already been slashed.', '750-990+', 'conj', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_28', 1),
  ('voc_toeic_0839', 'deck_toeic_990', 'en', 'with respect to', 'with respect to', '/wɪð rɪˈspekt tuː/', 'đối với, liên quan đến vấn đề gì', 'The committee expressed satisfaction with respect to our environmental compliance progress.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_29', 1),
  ('voc_toeic_0840', 'deck_toeic_990', 'en', 'in contrast to', 'in contrast to', '/ɪn ˈkɒntrɑːst tuː/', 'trái ngược hoàn toàn với', 'In contrast to last quarter’s massive losses, our Q3 operating margins improved remarkably.', '750-990+', 'prep phr', 'TOEIC,990,Unit-28', 'imported', 'toeic_28_30', 1),
  ('voc_toeic_0841', 'deck_toeic_990', 'en', 'economic', 'economic', '/ˌiːkəˈnɒmɪk/', 'thuộc về nền kinh tế quốc gia', 'The central bank introduced fiscal policies to stimulate national economic growth.', '750-990+', 'adj', 'TOEIC,990,Unit-29', 'imported', 'toeic_29_01', 1),
  ('voc_toeic_0842', 'deck_toeic_990', 'en', 'economical', 'economical', '/ˌiːkəˈnɒmɪkl/', 'tiết kiệm tiền bạc, tiết kiệm nhiên liệu', 'Hybrid sedans are far more economical to run than gas-guzzling sport utility vehicles.', '750-990+', 'adj', 'TOEIC,990,Unit-29', 'imported', 'toeic_29_02', 1),
