  ('voc_toeic_0844', 'deck_toeic_990', 'en', 'considerate', 'considerate', '/kənˈsɪdərət/', 'chu đáo, biết ân cần quan tâm người khác', 'It was very considerate of the department head to order lunch for the overtime crew.', '750-990+', 'adj', 'TOEIC,990,Unit-29', 'imported', 'toeic_29_04', 1),
  ('voc_toeic_0845', 'deck_toeic_990', 'en', 'sensible', 'sensible', '/ˈsensəbl/', 'hợp lý, biết điều, có óc phán đoán', 'Investing a portion of your savings in diversified index funds is a very sensible strategy.', '750-990+', 'adj', 'TOEIC,990,Unit-29', 'imported', 'toeic_29_05', 1),
  ('voc_toeic_0846', 'deck_toeic_990', 'en', 'sensitive', 'sensitive', '/ˈsensətɪv/', 'nhạy cảm, cơ mật (dữ liệu, thông tin)', 'The legal memo contains highly sensitive information regarding the pending intellectual patent.', '750-990+', 'adj', 'TOEIC,990,Unit-29', 'imported', 'toeic_29_06', 1),
  ('voc_toeic_0847', 'deck_toeic_990', 'en', 'successive', 'successive', '/səkˈsesɪv/', 'liên tiếp nhau không gián đoạn (= consecutive)', 'The retail conglomerate posted record profits for four successive fiscal quarters.', '750-990+', 'adj', 'TOEIC,990,Unit-29', 'imported', 'toeic_29_07', 1),
