  ('voc_toeic_0849', 'deck_toeic_990', 'en', 'comprehensible', 'comprehensible', '/ˌkɒmprɪˈhensəbl/', 'có thể hiểu được, dễ hiểu', 'The user manual translates complex technical jargon into easily comprehensible steps.', '750-990+', 'adj', 'TOEIC,990,Unit-29', 'imported', 'toeic_29_09', 1),
