  ('voc_toeic_0942', 'deck_toeic_990', 'en', 'reinstate', 'reinstate', '/ˌriːɪnˈsteɪt/', 'phục hồi chức vụ, tái lập chính sách', 'Management agreed to reinstate the employee discount program starting next week.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_12', 1),
  ('voc_toeic_0943', 'deck_toeic_990', 'en', 'facilitate', 'facilitate', '/fəˈsɪlɪteɪt/', 'tạo điều kiện thuận lợi, làm cho dễ dàng', 'Modern project management software facilitates seamless communication across distributed teams.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_13', 1),
  ('voc_toeic_0944', 'deck_toeic_990', 'en', 'consolidate', 'consolidate', '/kənˈsɒlɪdeɪt/', 'hợp nhất lại, củng cố vị thế vững mạnh', 'The bank consolidated its regional branch network to eliminate redundant overhead.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_14', 1),
  ('voc_toeic_0945', 'deck_toeic_990', 'en', 'prescribe', 'prescribe', '/prɪˈskraɪb/', 'quy định cụ thể quy tắc/biện pháp thi hành', 'Federal guidelines prescribe mandatory daily safety inspections for commercial aircraft.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_15', 1),
  ('voc_toeic_0946', 'deck_toeic_990', 'en', 'curtail', 'curtail', '/kɜːˈteɪl/', 'cắt giảm bớt, hạn chế (chi phí, hoạt động)', 'The company curtailed international travel expenses in response to slumping Q2 profits.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_16', 1),
  ('voc_toeic_0947', 'deck_toeic_990', 'en', 'quicken', 'quicken', '/ˈkwɪkən/', 'làm nhanh thêm, đẩy nhanh tiến trình', 'Automation and modular components helped quicken the tempo of chassis assembly.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_17', 1),
  ('voc_toeic_0948', 'deck_toeic_990', 'en', 'disseminate', 'disseminate', '/dɪˈsemɪneɪt/', 'phổ biến, truyền bá thông tin rộng rãi', 'Human resources will disseminate the revised corporate conduct handbook by email.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_18', 1),
  ('voc_toeic_0949', 'deck_toeic_990', 'en', 'jeopardize', 'jeopardize', '/ˈdʒepədaɪz/', 'gây nguy hiểm, liều lĩnh đe dọa sự an toàn', 'Failing to meet client data security standards could jeopardize the entire contract.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_19', 1),
  ('voc_toeic_0950', 'deck_toeic_990', 'en', 'ratify', 'ratify', '/ˈrætɪfaɪ/', 'phê chuẩn chính thức (hiệp định, điều ước)', 'The union members voted by a 70% majority to ratify the new three-year labor pact.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_20', 1);

INSERT OR REPLACE INTO vocabulary (
  id, deck_id, language, word, normalized_word, pronunciation, meaning_vi, example, level, part_of_speech, tags, source_type, seed_key, seed_version
) VALUES
  ('voc_toeic_0951', 'deck_toeic_990', 'en', 'substantiate', 'substantiate', '/səbˈstænʃieɪt/', 'chứng minh bằng bằng chứng xác thực', 'The claimant failed to substantiate her damage claims with itemized purchase receipts.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_21', 1),
  ('voc_toeic_0952', 'deck_toeic_990', 'en', 'peruse', 'peruse', '/pəˈruːz/', 'đọc kỹ lưỡng, xem xét cẩn thận từng chữ', 'Please peruse the contract provisions thoroughly before signing on the dotted line.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_22', 1),
  ('voc_toeic_0953', 'deck_toeic_990', 'en', 'supersede', 'supersede', '/ˌsuːpəˈsiːd/', 'thay thế cái cũ, chiếm chỗ (= replace)', 'The updated 2026 corporate safety guidelines supersede all previously issued manuals.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_23', 1),
  ('voc_toeic_0954', 'deck_toeic_990', 'en', 'authorize', 'authorize', '/ˈɔːθəraɪz/', 'ủy quyền, cho phép chính thức bằng văn bản', 'Only the Chief Financial Officer is authorized to approve capital purchases over $50,000.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_24', 1),
  ('voc_toeic_0955', 'deck_toeic_990', 'en', 'reaffirm', 'reaffirm', '/ˌriːəˈfɜːm/', 'tái khẳng định cam kết/chính sách', 'The chairman reaffirmed the corporation’s goal of achieving net-zero carbon operations.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_25', 1),
  ('voc_toeic_0956', 'deck_toeic_990', 'en', 'deter', 'deter', '/dɪˈtɜː(r)/', 'ngăn cản, làm nản lòng không dám làm', 'High penalty clauses are designed to deter suppliers from violating delivery schedules.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_26', 1),
  ('voc_toeic_0957', 'deck_toeic_990', 'en', 'alleviate', 'alleviate', '/əˈliːvieɪt/', 'làm dịu bớt, giảm nhẹ nỗi đau/tình trạng', 'Widening the commuter highway helped alleviate chronic rush-hour traffic gridlock.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_27', 1),
  ('voc_toeic_0958', 'deck_toeic_990', 'en', 'harmonize', 'harmonize', '/ˈhɑːmənaɪz/', 'hài hòa hóa các quy chuẩn/số liệu khác biệt', 'Cross-border regulators strive to harmonize pharmaceutical testing standards.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_28', 1),
  ('voc_toeic_0959', 'deck_toeic_990', 'en', 'culminate', 'culminate', '/ˈkʌlmɪneɪt/', 'lên đến đỉnh điểm, kết thúc bằng kết quả', 'Months of tense negotiations culminated in a historic multi-billion-dollar aerospace merger.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_29', 1),
  ('voc_toeic_0960', 'deck_toeic_990', 'en', 'mitigate', 'mitigate', '/ˈmɪtɪɡeɪt/', 'giảm nhẹ, làm dịu bớt rủi ro/thiệt hại', 'Hedging strategies helped the export firm mitigate currency fluctuation risks.', '750-990+', 'v', 'TOEIC,990,Unit-32', 'imported', 'toeic_32_30', 1),
  ('voc_toeic_0961', 'deck_toeic_990', 'en', 'refurbishment', 'refurbishment', '/ˌriːˈfɜːbɪʃmənt/', 'sự tân trang làm mới cơ sở (= remodeling / renovation)', 'The downtown hotel reopened after an extensive twenty-million-dollar refurbishment.', '750-990+', 'n', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_01', 1),
  ('voc_toeic_0962', 'deck_toeic_990', 'en', 'apparel', 'apparel', '/əˈpærəl/', 'trang phục quần áo may mặc (= clothing / attire)', 'The boutique retailer specializes in high-end business apparel for women.', '750-990+', 'n', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_02', 1),
  ('voc_toeic_0963', 'deck_toeic_990', 'en', 'patronage', 'patronage', '/ˈpætrənɪdʒ/', 'sự lui tới ủng hộ của khách quen (= support)', 'We sincerely thank you for your ongoing patronage of our family-owned bookstore.', '750-990+', 'n', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_03', 1),
  ('voc_toeic_0964', 'deck_toeic_990', 'en', 'hasten', 'hasten', '/ˈheɪsn/', 'làm cho nhanh hơn, thúc đẩy (= expedite / rush)', 'Innovative logistics software hastened parcel handling at regional sorting hubs.', '750-990+', 'v', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_04', 1),
  ('voc_toeic_0965', 'deck_toeic_990', 'en', 'convenience', 'convenience', '/kənˈviːniəns/', 'tiện nghi thuận tiện cho đời sống (= amenity)', 'The suburban condo complex offers conveniences such as covered parking and a gym.', '750-990+', 'n', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_05', 1),
  ('voc_toeic_0966', 'deck_toeic_990', 'en', 'prospective', 'prospective', '/prəˈspektɪv/', 'tiềm năng, triển vọng tương lai (= potential)', 'The sales representative pitched the software demo to prospective corporate clients.', '750-990+', 'adj', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_06', 1),
  ('voc_toeic_0967', 'deck_toeic_990', 'en', 'inaugurate', 'inaugurate', '/ɪˈnɔːɡjəreɪt/', 'khai mạc, khánh thành mở màn (= open / start)', 'The mayor will inaugurate the new international technology park on Monday.', '750-990+', 'v', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_07', 1),
  ('voc_toeic_0968', 'deck_toeic_990', 'en', 'remit', 'remit', '/rɪˈmɪt/', 'chuyển tiền hoàn trả (= send money / pay / reimburse)', 'The client agreed to remit the outstanding invoice balance via electronic wire.', '750-990+', 'v', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_08', 1),
  ('voc_toeic_0969', 'deck_toeic_990', 'en', 'delicate', 'delicate', '/ˈdelɪkət/', 'mỏng manh, dễ vỡ hư hại (= sensitive / fragile)', 'Handle delicate optical measuring sensors with utmost caution during transit.', '750-990+', 'adj', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_09', 1),
  ('voc_toeic_0970', 'deck_toeic_990', 'en', 'complimentary', 'complimentary', '/ˌkɒmplɪˈmentri/', 'miễn phí kèm theo dịch vụ (= free of charge)', 'The airline provides complimentary beverage service on all domestic flights.', '750-990+', 'adj', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_10', 1),
  ('voc_toeic_0971', 'deck_toeic_990', 'en', 'inquire', 'inquire', '/ɪnˈkwaɪə(r)/', 'hỏi thăm, thắc mắc thông tin (= ask / request info)', 'Prospective tenants called the property leasing office to inquire about vacant lofts.', '750-990+', 'v', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_11', 1),
  ('voc_toeic_0972', 'deck_toeic_990', 'en', 'in lieu of', 'in lieu of', '/ɪn ljuː əv/', 'thay cho, thay thế vào vị trí (= instead of)', 'The award winner received corporate stock options in lieu of a cash bonus.', '750-990+', 'prep phr', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_12', 1),
  ('voc_toeic_0973', 'deck_toeic_990', 'en', 'timetable', 'timetable', '/ˈtaɪmteɪbl/', 'thời gian biểu lịch trình (= schedule / itinerary)', 'The updated train timetable reflects expanded commuter service during peak hours.', '750-990+', 'n', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_13', 1),
  ('voc_toeic_0974', 'deck_toeic_990', 'en', 'merchant', 'merchant', '/ˈmɜːtʃənt/', 'thương gia, người bán hàng (= seller / vendor)', 'Online merchants must comply with secure payment gateway cryptography standards.', '750-990+', 'n', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_14', 1),
  ('voc_toeic_0975', 'deck_toeic_990', 'en', 'fluctuate', 'fluctuate', '/ˈflʌktʃueɪt/', 'dao động lên xuống thất thường (= vary / oscillate)', 'Gasoline prices fluctuate wildly depending on crude oil market volatility.', '750-990+', 'v', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_15', 1),
  ('voc_toeic_0976', 'deck_toeic_990', 'en', 'mandatory', 'mandatory', '/ˈmændətəri/', 'bắt buộc theo quy định (= compulsory / obligatory)', 'Attendance at the annual corporate cybersecurity training module is strictly mandatory.', '750-990+', 'adj', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_16', 1),
  ('voc_toeic_0977', 'deck_toeic_990', 'en', 'reposition', 'reposition', '/ˌriːpəˈzɪʃn/', 'chuyển dời vị trí, tái định vị (= move / relocate)', 'The retail chain will reposition its regional flagship store to the central boulevard.', '750-990+', 'v', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_17', 1),
  ('voc_toeic_0978', 'deck_toeic_990', 'en', 'adjacent to', 'adjacent to', '/əˈdʒeɪsnt tuː/', 'ngay kế bên, sát cạnh (= next to / beside)', 'The cafeteria is located adjacent to the second-floor auditoriums.', '750-990+', 'prep phr', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_18', 1),
  ('voc_toeic_0979', 'deck_toeic_990', 'en', 'apprise', 'apprise', '/əˈpraɪz/', 'báo cho biết, cung cấp thông tin (= inform / notify)', 'The plant manager apprised the board of directors of recent productivity gains.', '750-990+', 'v', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_19', 1),
  ('voc_toeic_0980', 'deck_toeic_990', 'en', 'mandate', 'mandate', '/ˈmændeɪt/', 'ra lệnh bắt buộc thi hành (= require / stipulate)', 'New city building codes mandate solar panel installation on all new commercial structures.', '750-990+', 'v', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_20', 1),
  ('voc_toeic_0981', 'deck_toeic_990', 'en', 'procure', 'procure', '/prəˈkjʊə(r)/', 'mua sắm vật tư, trang thiết bị (= obtain / acquire)', 'The purchasing department worked overtime to procure emergency medical face masks.', '750-990+', 'v', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_21', 1),
  ('voc_toeic_0982', 'deck_toeic_990', 'en', 'subsequent', 'subsequent', '/ˈsʌbsɪkwənt/', 'tiếp sau đó, xảy ra sau (= following / later)', 'Initial trials were inconclusive, but subsequent tests proved remarkably effective.', '750-990+', 'adj', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_22', 1),
  ('voc_toeic_0983', 'deck_toeic_990', 'en', 'unprecedented', 'unprecedented', '/ʌnˈpresɪdentɪd/', 'chưa từng có tiền lệ trong lịch sử (= novel)', 'Soaring online holiday retail orders surged to an unprecedented all-time record.', '750-990+', 'adj', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_23', 1),
  ('voc_toeic_0984', 'deck_toeic_990', 'en', 'shortfall', 'shortfall', '/ˈʃɔːtfɔːl/', 'sự thiếu hụt số tiền/sản lượng (= deficit)', 'A three-million-dollar tax shortfall forced the municipality to pause road repaving.', '750-990+', 'n', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_24', 1),
  ('voc_toeic_0985', 'deck_toeic_990', 'en', 'versatile', 'versatile', '/ˈvɜːsətaɪl/', 'đa năng, thích ứng linh hoạt (= adaptable / flexible)', 'The new laser-cutting apparatus is versatile enough to slice metals, ceramics, and wood.', '750-990+', 'adj', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_25', 1),
  ('voc_toeic_0986', 'deck_toeic_990', 'en', 'lucrative', 'lucrative', '/ˈluːkrətɪv/', 'siêu lợi nhuận, kiếm nhiều tiền (= profitable)', 'The telecommunications conglomerate landed a lucrative five-year government satellite deal.', '750-990+', 'adj', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_26', 1),
  ('voc_toeic_0987', 'deck_toeic_990', 'en', 'defect', 'defect', '/ˈdiːfekt/', 'khuyết tật lỗi sản phẩm (= imperfection / flaw)', 'Engineers detected a minor metallurgical defect in the front axle casing.', '750-990+', 'n', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_27', 1),
  ('voc_toeic_0988', 'deck_toeic_990', 'en', 'prerequisite', 'prerequisite', '/ˌpriːˈrekwəzɪt/', 'điều kiện tiên quyết bắt buộc (= requirement)', 'Fluent spoken Spanish is a prerequisite qualification for the South American sales post.', '750-990+', 'n, adj', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_28', 1),
  ('voc_toeic_0989', 'deck_toeic_990', 'en', 'rescind', 'rescind', '/rɪˈsɪnd/', 'hủy bỏ bãi bỏ hiệu lực hợp đồng (= cancel / revoke)', 'The buyer reserved the legal right to rescind the purchase pact if title deed issues arose.', '750-990+', 'v', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_29', 1),
  ('voc_toeic_0990', 'deck_toeic_990', 'en', 'inconsequential', 'inconsequential', '/ɪnˌkɒnsɪˈkwenʃl/', 'không đáng kể, không quan trọng (= trivial / minor)', 'The slight difference in cabin noise was deemed inconsequential by test drivers.', '750-990+', 'adj', 'TOEIC,990,Unit-33', 'imported', 'toeic_33_30', 1);

